import itertools
views=[('A','B','C'),('C','B','E'),('F','C','E')]
adj=set()
for v in views:
    for a,b in itertools.combinations(v,2): adj.add(frozenset((a,b)))
L='ABCDEF'; sols=set()
def pairings(s):
    if not s: yield []; return
    a=s[0]
    for b in s[1:]:
        rest=[x for x in s if x not in (a,b)]
        for p in pairings(rest): yield [(a,b)]+p
for p in pairings(list(L)):
    if all(frozenset(x) not in adj for x in p):
        for x,y in p:
            if x=='A': sols.add(y)
            if y=='A': sols.add(x)
assert sols=={'E'}
